// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 seed) public {
        // Choose a fuzzed block number that is a multiple of 15 (admissible domain kept wide).
        uint256 n = bound(seed, 0, type(uint256).max / 15 - 1) * 15;

        address actor = makeAddr("actor");
        vm.deal(actor, 10 ether);

        vm.roll(n);
        vm.warp(n + 1); // fresh timestamp > pastBlockTime (0)

        vm.prank(actor);
        (bool ok,) = address(c).call{value: 10 ether}("");
        assertTrue(ok);

        // Reference: on a block number divisible by 15 the whole balance is paid out.
        // Mutant: pays on % 15 == 1 instead, so balance remains 10 ether here.
        assertTrue(address(c).balance == 0);
    }
}
